 44→ *   6. Publish IPNS record via CipherBox API (ipns-publish)
 45→ *   7. Cleanup: unpin from PSA (byo-unpin)
 46→ */
 47→export async function runByoFileWorkload(
 48→  pc: ByoPoolClient,
 49→  opts: ByoFileWorkloadOptions
 50→): Promise<void> {
 51→  const { fileCount, minSize, maxSize, verifyDownloads } = opts;
 52→  if (minSize < 0 || maxSize < minSize) {
 53→    throw new Error(`Invalid size bounds: minSize=${minSize}, maxSize=${maxSize}`);
 54→  }
 55→
 56→  const isPsa = pc.provider instanceof PsaProvider;
 57→  const { client, rootIpnsName, metrics } = pc;
 58→
 59→  for (let i = 0; i < fileCount; i++) {
 60→    const size = minSize + Math.floor(Math.random() * (maxSize - minSize));
 61→    const data = new Uint8Array(size);
 62→    // crypto.getRandomValues() has a 65536 byte limit per call
 63→    for (let offset = 0; offset < size; offset += 65536) {
 64→      const chunk = new Uint8Array(data.buffer, offset, Math.min(65536, size - offset));
 65→      crypto.getRandomValues(chunk);
 66→    }
 67→
 68→    try {
 69→      let cid: string;
 70→      let pinSize: number;
 71→
 72→      if (isPsa) {
 73→        // PSA transient relay flow
 74→        // Step 1: Upload to CipherBox to make content available on IPFS network
 75→        const relayResult = await metrics.measure(
 76→          'psa-relay-upload',
 77→          async () => {
 78→            const axiosInstance = client.getContext().axiosInstance!;
 79→            const blob = new Blob([data as BlobPart]);
 80→            const formData = new FormData();
 81→            formData.append('file', blob);
 82→            const res = await axiosInstance.post<{ cid: string; size: number }>(
 83→              '/ipfs/upload',
 84→              formData
 85→            );
 86→            return res.data;
 87→          },
 88→          size
 89→        );
 90→
 91→        cid = relayResult.cid;
 92→        pinSize = relayResult.size;
 93→
 94→        // Step 2: Pin by CID on PSA service
 95→        await metrics.measure('psa-pin-by-cid', async () => {
 96→          await (pc.provider as PsaProvider).pinByCid(cid, `load-${pc.id}-file-${i}`);
 97→        });
 98→
 99→        // Step 3: Unpin from CipherBox relay (content now on PSA service)
100→        await metrics.measure('psa-relay-unpin', async () => {
101→          const axiosInstance = client.getContext().axiosInstance!;
102→          await axiosInstance.post('/ipfs/unpin', { cid });
103→        });
104→      } else {
105→        // Kubo direct upload flow
106→        const pinResult = await metrics.measure(
107→          'byo-pin',
108→          () => pc.provider.pin(data, `load-${pc.id}-file-${i}`),
109→          size
110→        );
111→        cid = pinResult.cid;
112→        pinSize = pinResult.size;
113→      }
114→
115→      // Register CID with CipherBox API (both modes)
116→      await metrics.measure('register-cid', async () => {
117→        const axiosInstance = client.getContext().axiosInstance!;
118→        await axiosInstance.post('/ipfs/register-cid', { cid, sizeBytes: pinSize });
119→      });
120→
121→      // Publish IPNS record via CipherBox API (measure raw IPNS API latency)
122→      await metrics.measure('ipns-publish', async () => {
123→        const axiosInstance = client.getContext().axiosInstance!;
124→        // Use publish-batch endpoint with a single record to measure IPNS publish latency
125→        // without coupling to the full upload flow's folder update
126→        await axiosInstance.post('/ipns/publish-batch', {
127→          records: [
128→            {
129→              ipnsName: rootIpnsName,
130→              cid,
131→            },
132→          ],
133→        });
134→      });
135→
136→      // Optional: verify download (Kubo only -- PSA does not support content retrieval)
137→      if (verifyDownloads && !isPsa) {
138→        await metrics.measure(
139→          'byo-download',
140→          async () => {
141→            const downloaded = await pc.provider.get(cid);
142→            if (downloaded.length !== data.length) {
143→              throw new Error(
144→                `[Client ${pc.id}] Size mismatch: uploaded ${data.length}, downloaded ${downloaded.length}`
145→              );
146→            }
147→            return downloaded;
148→          },
149→          size
150→        );
151→      }
152→
153→      // Cleanup: unpin from external provider
154→      await metrics.measure('byo-unpin', () => pc.provider.unpin(cid));
155→    } catch (err) {
156→      console.warn(
157→        `[Client ${pc.id}] BYO file ${i} failed: ${(err as Error).message?.slice(0, 150)}`
158→      );
159→    }
160→  }
161→}
