  1→/**
  2→ * Load Test Client Pool
  3→ *
  4→ * Manages N CipherBoxClient instances, each with its own test account.
  5→ * Creates accounts in parallel, distributes workloads, and collects metrics.
  6→ *
  7→ * Reuses the shared createTestAccount/deleteTestAccount from sdk-e2e
  8→ * to avoid duplicating the 5-step account provisioning sequence.
  9→ */
 10→
 11→import {
 12→  createTestAccount,
 13→  deleteTestAccount,
 14→  type TestAccount,
 15→} from '../../../sdk-e2e/src/fixtures/test-harness';
 16→import { MetricsCollector, type OperationMetrics } from './metrics';
 17→import { printSummary, toJsonReport } from './reporter';
 18→import {
 19→  KuboProvider,
 20→  PsaProvider,
 21→  type PinningProvider,
 22→  type PinningMode,
 23→  type ExternalProviderConfig,
 24→} from '@cipherbox/sdk-core';
 25→
 26→const API_URL = process.env.LOAD_TEST_API_URL ?? 'http://localhost:3000';
 27→const SECRET = process.env.LOAD_TEST_SECRET ?? 'e2e-test-secret-do-not-use-in-production';
 28→
 29→/** BYO external provider config from environment variables */
 30→export const BYO_ENDPOINT = process.env.BYO_IPFS_ENDPOINT; // e.g., https://api.pinata.cloud/psa
 31→export const BYO_AUTH_TOKEN = process.env.BYO_IPFS_AUTH_TOKEN ?? '';
 32→export const BYO_PROTOCOL = (process.env.BYO_IPFS_PROTOCOL ?? 'kubo') as 'kubo' | 'psa';
 33→export const BYO_PROVIDER_NAME = process.env.BYO_IPFS_PROVIDER_NAME ?? 'external';
 34→
 35→export interface PoolClient extends TestAccount {
 36→  id: number;
 37→  metrics: MetricsCollector;
 38→}
 39→
 40→export interface ClientPoolOptions {
 41→  clientCount: number;
 42→  label: string;
 43→}
 44→
 45→/** Options for creating a pool of BYO-mode clients */
 46→export interface ByoPoolOptions extends ClientPoolOptions {
 47→  /** External provider config -- all BYO clients share this provider */
 48→  externalProvider: ExternalProviderConfig;
 49→  /** Pinning mode for BYO clients */
 50→  pinningMode: 'external' | 'dual';
 51→}
 52→
 53→/** A pool client augmented with BYO provider and mode */
 54→export interface ByoPoolClient extends PoolClient {
 55→  provider: PinningProvider;
 56→  pinningMode: PinningMode;
 57→  externalProvider: ExternalProviderConfig;
 58→}
 59→
 60→/**
 61→ * Create a pool of N authenticated CipherBoxClient instances.
 62→ *
 63→ * Each client has its own test account, vault, metrics collector, and
 64→ * instance-scoped axios (no shared singleton).
 65→ */
 66→export async function createClientPool(opts: ClientPoolOptions): Promise<PoolClient[]> {
 67→  const { clientCount, label } = opts;
 68→  console.log(`Creating ${clientCount} test accounts for "${label}"...`);
 69→  const start = performance.now();
 70→
 71→  // Create accounts in parallel batches of 5 to avoid overwhelming the API
 72→  const clients: PoolClient[] = [];
 73→  const batchSize = 5;
 74→
 75→  for (let batch = 0; batch < clientCount; batch += batchSize) {
 76→    const batchEnd = Math.min(batch + batchSize, clientCount);
 77→    const promises = [];
 78→
 79→    for (let i = batch; i < batchEnd; i++) {
 80→      promises.push(
 81→        createTestAccount({
 82→          apiUrl: API_URL,
 83→          secret: SECRET,
 84→          label: `${label}-${i}`,
 85→          emailPrefix: 'load',
 86→        }).then((account): PoolClient => ({ ...account, id: i, metrics: new MetricsCollector() }))
 87→      );
 88→    }
 89→
 90→    const results = await Promise.allSettled(promises);
 91→    for (const result of results) {
 92→      if (result.status === 'fulfilled') {
 93→        clients.push(result.value);
 94→      } else {
 95→        console.warn(`Failed to create pool client: ${result.reason}`);
 96→      }
 97→    }
 98→  }
 99→
100→  const elapsed = performance.now() - start;
101→  console.log(
102→    `Created ${clients.length}/${clientCount} clients in ${(elapsed / 1000).toFixed(1)}s`
103→  );
104→
105→  return clients;
106→}
107→
108→/**
109→ * Destroy all clients in the pool and delete test accounts.
110→ */
111→export async function destroyClientPool(pool: PoolClient[]): Promise<void> {
112→  console.log(`Cleaning up ${pool.length} test accounts...`);
113→  for (const pc of pool) {
114→    pc.client.destroy();
115→    // Zero harness-owned key material (client.destroy() only clears its internal copies)
116→    pc.privateKey.fill(0);
117→    pc.rootFolderKey.fill(0);
118→    pc.rootIpnsKeypair.privateKey.fill(0);
119→    await deleteTestAccount(pc, API_URL);
120→  }
121→}
122→
123→/**
124→ * Create a pool of N BYO-mode authenticated CipherBoxClient instances.
125→ *
126→ * Each client has its own test account plus a PinningProvider instance
127→ * (KuboProvider or PsaProvider) for external pinning.
128→ *
129→ * Returns an empty array (with warning) if BYO_IPFS_ENDPOINT is not set,
130→ * allowing scenarios to skip gracefully.
131→ */
132→export async function createByoClientPool(opts: ByoPoolOptions): Promise<ByoPoolClient[]> {
133→  if (!BYO_ENDPOINT) {
134→    console.warn(
135→      'BYO_IPFS_ENDPOINT not set -- skipping BYO pool creation. ' +
136→        'Set BYO_IPFS_ENDPOINT, BYO_IPFS_AUTH_TOKEN, and optionally BYO_IPFS_PROTOCOL to run BYO scenarios.'
137→    );
138→    return [];
139→  }
140→
141→  const basePool = await createClientPool({
142→    clientCount: opts.clientCount,
143→    label: opts.label,
144→  });
145→
146→  const byoPool: ByoPoolClient[] = basePool.map((pc) => {
147→    const provider: PinningProvider =
148→      opts.externalProvider.protocol === 'psa'
149→        ? new PsaProvider(opts.externalProvider.endpoint, opts.externalProvider.authToken)
150→        : new KuboProvider(opts.externalProvider.endpoint, opts.externalProvider.authToken);
151→
152→    return {
153→      ...pc,
154→      provider,
155→      pinningMode: opts.pinningMode,
156→      externalProvider: opts.externalProvider,
157→    };
158→  });
159→
160→  console.log(
161→    `BYO pool: ${byoPool.length} clients with ${opts.externalProvider.protocol} provider ` +
162→      `(mode: ${opts.pinningMode}, endpoint: ${opts.externalProvider.endpoint})`
163→  );
164→
165→  return byoPool;
166→}
167→
168→/**
169→ * Aggregate metrics from all pool clients, print summary, and return metrics.
170→ * Extracts the repeated boilerplate from every load test scenario.
171→ */
172→export async function aggregateAndReport(
173→  scenarioName: string,
174→  pool: PoolClient[]
175→): Promise<OperationMetrics[]> {
176→  const allMetrics = new MetricsCollector();
177→
178→  let minTimestamp = Infinity;
179→  let maxTimestamp = 0;
180→
181→  for (const pc of pool) {
182→    for (const sample of pc.metrics.getReadonlySamples()) {
183→      allMetrics.record(sample);
184→      if (sample.timestamp < minTimestamp) minTimestamp = sample.timestamp;
185→      if (sample.timestamp > maxTimestamp) maxTimestamp = sample.timestamp;
186→    }
187→  }
188→
189→  // Set collector timing from sample timestamps for accurate throughput calculation
190→  allMetrics.setElapsedMs(maxTimestamp > minTimestamp ? maxTimestamp - minTimestamp : 1);
191→
192→  const totalDuration = maxTimestamp > minTimestamp ? maxTimestamp - minTimestamp : 0;
193→  const metrics = allMetrics.getMetrics();
194→
195→  printSummary(scenarioName, metrics, totalDuration, pool.length);
196→
197→  // Write JSON report to file for CI artifact upload
198→  const reportJson = toJsonReport(scenarioName, metrics, totalDuration, pool.length);
199→  console.log('\nJSON Report:\n' + reportJson);
200→
201→  try {
202→    const fs = await import('node:fs/promises');
203→    const slug = scenarioName.toLowerCase().replace(/[^a-z0-9]+/g, '-');
204→    await fs.writeFile(`metrics-${slug}.json`, reportJson);
205→  } catch (err) {
206→    console.warn(`Failed to write metrics report: ${(err as Error).message}`);
207→  }
208→
209→  return metrics;
210→}
