          previousMode !== 'cipherbox'
            ? {
                endpoint: savedConfig?.endpoint ?? '',
                authToken: savedConfig?.authToken ?? '',
                protocol: 'kubo',
              }
            : { endpoint: 'cipherbox', protocol: 'cipherbox' }
        );
