 1→/** Result of a pin operation */
 2→export type PinResult = {
 3→  cid: string;
 4→  size: number;
 5→};
 6→
 7→/** Status of a pin */
 8→export type PinStatus = {
 9→  cid: string;
10→  status: 'queued' | 'pinning' | 'pinned' | 'failed';
11→};
12→
13→/** Abstract pinning provider -- implemented by KuboProvider and PsaProvider */
14→export interface PinningProvider {
15→  /** Upload and pin data, returning CID and size */
16→  pin(data: Uint8Array, name?: string): Promise<PinResult>;
17→  /** Remove a pin by CID */
18→  unpin(cid: string): Promise<void>;
19→  /** Check pin status by CID */
20→  status(cid: string): Promise<PinStatus>;
21→  /** Fetch pinned content by CID */
22→  get(cid: string): Promise<Uint8Array>;
23→}
24→
25→/** User-selectable pinning mode */
26→export type PinningMode = 'cipherbox' | 'external' | 'dual';
27→
