 21→/** Local storage key for the BYO config IPNS name (not sensitive -- public identifier) */
 22→const BYO_IPNS_NAME_KEY = 'cipherbox-byo-ipns-name';
 23→
 24→type SavedConfig = {
 25→  mode: PinningMode;
 26→  endpoint: string;
 27→  authToken: string;
