 30→/**
 31→ * Encrypt ByoIpfsConfig with user's secp256k1 public key (ECIES).
 32→ * Follows the same pattern as @cipherbox/core registry/bin encrypt.
 33→ */
 34→async function encryptByoConfig(
 35→  config: ByoIpfsConfig,
 36→  userPublicKey: Uint8Array
 37→): Promise<Uint8Array> {
 38→  const plaintext = new TextEncoder().encode(JSON.stringify(config));
 39→  try {
 40→    return await wrapKey(plaintext, userPublicKey);
 41→  } finally {
 42→    clearBytes(plaintext);
 43→  }
 44→}
 45→
 46→/**
 47→ * Decrypt ByoIpfsConfig with user's secp256k1 private key (ECIES).
 48→ */
 49→async function decryptByoConfig(
 50→  encrypted: Uint8Array,
 51→  userPrivateKey: Uint8Array
 52→): Promise<ByoIpfsConfig> {
 53→  const plaintext = await unwrapKey(encrypted, userPrivateKey);
 54→  try {
 55→    const json = new TextDecoder().decode(plaintext);
 56→    return JSON.parse(json) as ByoIpfsConfig;
 57→  } finally {
 58→    clearBytes(plaintext);
 59→  }
 60→}
