 62→/**
 63→ * STORAGE tab for the Settings page.
 64→ *
 65→ * Allows users to configure their IPFS pinning mode, external node settings,
 66→ * test connections, and persist BYO config as an encrypted IPNS entry
 67→ * (zero-knowledge -- server never sees credentials).
 68→ */
 69→export function StorageTab() {
 70→  const [mode, setMode] = useState<PinningMode>('cipherbox');
 71→  const [endpoint, setEndpoint] = useState('');
 72→  const [authToken, setAuthToken] = useState('');
 73→  const [savedConfig, setSavedConfig] = useState<SavedConfig | null>(null);
 74→  const [testResult, setTestResult] = useState<ConnectionTestResult | null>(null);
 75→  const [isSaving, setIsSaving] = useState(false);
 76→  const [isLoading, setIsLoading] = useState(true);
 77→  const [saveError, setSaveError] = useState<string | null>(null);
 78→
 79→  const vaultKeypair = useAuthStore((s) => s.vaultKeypair);
 80→  const teeKeys = useAuthStore((s) => s.teeKeys);
 81→  const { usedBytes } = useQuotaStore();
 82→
 83→  // Dirty tracking
 84→  const isDirty = useMemo(() => {
 85→    if (!savedConfig) {
 86→      return mode !== 'cipherbox' || endpoint !== '' || authToken !== '';
 87→    }
 88→    return (
 89→      mode !== savedConfig.mode ||
 90→      endpoint !== savedConfig.endpoint ||
 91→      authToken !== savedConfig.authToken
 92→    );
 93→  }, [mode, endpoint, authToken, savedConfig]);
 94→
 95→  const endpointDirty = savedConfig ? endpoint !== savedConfig.endpoint : endpoint !== '';
 96→  const tokenDirty = savedConfig ? authToken !== savedConfig.authToken : authToken !== '';
 97→
 98→  // Load saved config from encrypted IPNS entry on mount
 99→  useEffect(() => {
100→    let cancelled = false;
101→
102→    async function loadConfig() {
103→      if (!vaultKeypair?.privateKey) {
104→        setIsLoading(false);
105→        return;
106→      }
107→
108→      try {
109→        const keypair = await deriveByoConfigIpnsKeypair(vaultKeypair.privateKey);
110→        const storedIpnsName = localStorage.getItem(BYO_IPNS_NAME_KEY);
111→
112→        // Use stored name or derived name
113→        const ipnsName = storedIpnsName || keypair.ipnsName;
114→
115→        // Try resolving the BYO config IPNS record
116→        const resolved = await resolveIpnsRecord(ipnsName);
117→        if (cancelled) return;
118→
119→        if (resolved?.cid) {
120→          const encrypted = await fetchFromIpfs(resolved.cid);
121→          if (cancelled) return;
122→
123→          const config = await decryptByoConfig(encrypted, vaultKeypair.privateKey);
124→          if (cancelled) return;
125→
126→          setMode(config.pinningMode);
127→          setEndpoint(config.externalProvider?.endpoint ?? '');
128→          setAuthToken(config.externalProvider?.authToken ?? '');
129→          setSavedConfig({
130→            mode: config.pinningMode,
131→            endpoint: config.externalProvider?.endpoint ?? '',
132→            authToken: config.externalProvider?.authToken ?? '',
133→          });
134→
135→          // Cache the IPNS name
136→          localStorage.setItem(BYO_IPNS_NAME_KEY, ipnsName);
137→        }
138→      } catch {
139→        // No saved config or decryption failed -- use defaults
140→      } finally {
141→        if (!cancelled) {
142→          setIsLoading(false);
143→        }
144→      }
145→    }
146→
147→    loadConfig();
148→    return () => {
149→      cancelled = true;
150→    };
151→  }, [vaultKeypair]);
152→
153→  const handleSave = useCallback(async () => {
154→    if (!vaultKeypair?.privateKey || !vaultKeypair?.publicKey || isSaving) return;
155→    setIsSaving(true);
156→    setSaveError(null);
157→
158→    try {
159→      const config: ByoIpfsConfig = {
160→        pinningMode: mode,
161→        externalProvider:
162→          mode !== 'cipherbox'
163→            ? {
164→                endpoint,
165→                authToken,
166→                protocol: testResult?.protocol ?? 'kubo',
167→                providerName: testResult?.version,
168→              }
169→            : null,
170→      };
171→
172→      const encrypted = await encryptByoConfig(config, vaultKeypair.publicKey);
173→
174→      const blob = new Blob([encrypted as BlobPart]);
175→      const { cid } = await addToIpfs(blob);
176→
177→      const byoKeypair = await deriveByoConfigIpnsKeypair(vaultKeypair.privateKey);
178→
179→      let sequenceNumber = BigInt(0);
180→      const storedIpnsName = localStorage.getItem(BYO_IPNS_NAME_KEY);
181→      if (storedIpnsName) {
182→        try {
183→          const existing = await resolveIpnsRecord(storedIpnsName);
184→          if (existing?.sequenceNumber) {
185→            sequenceNumber = BigInt(existing.sequenceNumber);
186→          }
187→        } catch {
188→          // First publish -- sequence 0
189→        }
190→      }
191→
192→      let encryptedIpnsPrivateKey: string | undefined;
193→      let keyEpoch: number | undefined;
194→      if (teeKeys?.currentPublicKey) {
195→        const teePublicKey = hexToBytes(teeKeys.currentPublicKey);
196→        const wrappedKey = await wrapKey(byoKeypair.privateKey, teePublicKey);
197→        encryptedIpnsPrivateKey = bytesToHex(wrappedKey);
198→        keyEpoch = teeKeys.currentEpoch;
199→      }
200→
201→      await createAndPublishIpnsRecord({
202→        ipnsPrivateKey: byoKeypair.privateKey,
203→        ipnsName: byoKeypair.ipnsName,
204→        metadataCid: cid,
205→        sequenceNumber,
206→        encryptedIpnsPrivateKey,
207→        keyEpoch,
208→      });
209→
210→      localStorage.setItem(BYO_IPNS_NAME_KEY, byoKeypair.ipnsName);
211→
212→      setSavedConfig({
213→        mode,
214→        endpoint,
215→        authToken,
216→      });
217→
218→      // Reconfigure SDK client so uploads immediately use the updated mode
219→      reconfigurePinning(
220→        mode !== 'cipherbox' && config.externalProvider
221→          ? { mode, externalProvider: config.externalProvider }
222→          : undefined
223→      );
224→
225→      // Treat null savedConfig as implicit "cipherbox" mode (first-time user)
226→      const previousMode = savedConfig?.mode ?? 'cipherbox';
227→      const previousEndpoint = savedConfig?.endpoint ?? '';
228→      const providerChanged =
229→        (previousMode !== mode || previousEndpoint !== endpoint) && usedBytes > 0;
230→
231→      if (providerChanged && teeKeys?.currentPublicKey) {
232→        // ECIES-wrap source and destination provider configs for TEE
233→        const teePublicKey = hexToBytes(teeKeys.currentPublicKey);
234→
235→        const sourceConfig = JSON.stringify(
236→          previousMode !== 'cipherbox'
237→            ? {
238→                endpoint: savedConfig?.endpoint ?? '',
239→                authToken: savedConfig?.authToken ?? '',
240→                protocol: 'kubo',
241→              }
242→            : { endpoint: 'cipherbox', protocol: 'cipherbox' }
243→        );
244→        const destConfig = JSON.stringify({
245→          endpoint,
246→          authToken,
247→          protocol: testResult?.protocol ?? 'kubo',
248→        });
249→
250→        const sourceConfigEncrypted = bytesToHex(
251→          await wrapKey(new TextEncoder().encode(sourceConfig), teePublicKey)
252→        );
253→        const destConfigEncrypted = bytesToHex(
254→          await wrapKey(new TextEncoder().encode(destConfig), teePublicKey)
255→        );
256→
257→        await migrationApi.start(sourceConfigEncrypted, destConfigEncrypted);
258→      }
259→
260→      useQuotaStore.getState().fetchQuota();
261→    } catch (err) {
262→      setSaveError(
263→        err instanceof Error ? err.message : 'failed to save storage settings. try again.'
264→      );
265→    } finally {
266→      setIsSaving(false);
267→    }
268→  }, [
269→    vaultKeypair,
270→    mode,
271→    endpoint,
272→    authToken,
273→    testResult,
274→    teeKeys,
275→    savedConfig,
276→    usedBytes,
277→    isSaving,
278→  ]);
279→
280→  const handleDiscard = useCallback(() => {
281→    if (savedConfig) {
282→      setMode(savedConfig.mode);
283→      setEndpoint(savedConfig.endpoint);
284→      setAuthToken(savedConfig.authToken);
285→    } else {
286→      setMode('cipherbox');
287→      setEndpoint('');
288→      setAuthToken('');
289→    }
290→    setTestResult(null);
291→    setSaveError(null);
292→  }, [savedConfig]);
293→
294→  if (isLoading) {
295→    return (
296→      <div className="settings-storage">
297→        <p className="settings-section-description">loading storage settings...</p>
298→      </div>
299→    );
300→  }
301→
302→  return (
303→    <div className="settings-storage">
304→      {/* Pinning Mode Section */}
305→      <h3 className="settings-section-heading">{'// pinning mode'}</h3>
306→      <p className="settings-section-description">
307→        {
308→          'configure where your encrypted files are stored. all data remains encrypted -- your node only sees ciphertext.'
309→        }
310→      </p>
311→
312→      <fieldset className="storage-mode-selector" role="radiogroup" aria-label="Pinning mode">
313→        <div className="storage-mode-option">
314→          <label>
315→            <input
316→              type="radio"
317→              name="pinning-mode"
318→              value="cipherbox"
319→              checked={mode === 'cipherbox'}
320→              onChange={() => setMode('cipherbox')}
321→              aria-describedby="hint-cipherbox"
322→            />
323→            <span className="storage-mode-label">{'cipherbox only'}</span>
324→          </label>
325→          <p className="storage-mode-hint" id="hint-cipherbox">
326→            {'files pinned to cipherbox infrastructure (default)'}
327→          </p>
328→        </div>
329→        <div className="storage-mode-option">
330→          <label>
331→            <input
332→              type="radio"
333→              name="pinning-mode"
334→              value="external"
335→              checked={mode === 'external'}
336→              onChange={() => setMode('external')}
