345→        <div className="storage-mode-option">
346→          <label>
347→            <input
348→              type="radio"
349→              name="pinning-mode"
350→              value="dual"
351→              checked={mode === 'dual'}
352→              onChange={() => setMode('dual')}
353→              aria-describedby="hint-dual"
354→            />
355→            <span className="storage-mode-label">{'dual-pin (both)'}</span>
356→          </label>
357→          <p className="storage-mode-hint" id="hint-dual">
358→            {'primary pin to cipherbox, best-effort mirror to your node.'}
359→          </p>
360→        </div>
361→      </fieldset>
362→
363→      {/* Provider Configuration (shown when external or dual) */}
364→      {mode !== 'cipherbox' && (
365→        <div className="storage-provider-config">
366→          <h3 className="settings-section-heading">{'// external node'}</h3>
367→
368→          <label className="storage-field">
