  1→import { useCallback, useEffect, useState } from 'react';
  2→import { testConnection, type ConnectionTestResult } from '@cipherbox/sdk-core';
  3→import { wrapKey, hexToBytes, bytesToHex } from '@cipherbox/crypto';
  4→import { teeControllerConnectionTest } from '@cipherbox/api-client';
  5→import { useAuthStore } from '../../stores/auth.store';
  6→
  7→type ConnectionTestProps = {
  8→  endpoint: string;
  9→  authToken: string;
 10→  onTestResult?: (result: ConnectionTestResult | null) => void;
 11→};
 12→
 13→/**
 14→ * Connection test UI for BYO-IPFS node endpoint.
 15→ *
 16→ * Routes the connection test through the TEE worker to avoid browser CORS
 17→ * issues. Provider credentials are ECIES-encrypted before leaving the browser
 18→ * and decrypted only inside the TEE enclave for server-side probing.
 19→ *
 20→ * Falls back to browser-side testConnection() when TEE keys are unavailable.
 21→ */
 22→export function ConnectionTest({ endpoint, authToken, onTestResult }: ConnectionTestProps) {
 23→  const [testResult, setTestResult] = useState<ConnectionTestResult | null>(null);
 24→  const [isTesting, setIsTesting] = useState(false);
 25→
 26→  // Clear result when endpoint or authToken changes
 27→  useEffect(() => {
 28→    setTestResult(null);
 29→    onTestResult?.(null);
 30→  }, [endpoint, authToken]); // onTestResult intentionally excluded -- only fire on input changes
 31→
 32→  const handleTest = useCallback(async () => {
 33→    if (!endpoint || isTesting) return;
 34→    setIsTesting(true);
 35→    setTestResult(null);
 36→    onTestResult?.(null);
 37→
 38→    try {
 39→      // Try TEE-routed test first (avoids CORS, keeps credentials encrypted)
 40→      const teeKeys = useAuthStore.getState().teeKeys;
 41→
 42→      if (teeKeys?.currentPublicKey) {
 43→        const result = await teeRoutedTest(endpoint, authToken, teeKeys);
 44→        setTestResult(result);
 45→        onTestResult?.(result);
 46→      } else {
 47→        // Fallback: browser-side test when TEE keys not available
 48→        console.warn('TEE keys not available, falling back to browser-side connection test');
 49→        const result = await testConnection(endpoint, authToken || undefined);
 50→        setTestResult(result);
 51→        onTestResult?.(result);
 52→      }
 53→    } catch {
 54→      const errorResult: ConnectionTestResult = {
 55→        success: false,
 56→        latencyMs: 0,
 57→        error: 'connection test failed. please try again.',
 58→      };
 59→      setTestResult(errorResult);
 60→      onTestResult?.(errorResult);
 61→    } finally {
 62→      setIsTesting(false);
 63→    }
 64→  }, [endpoint, authToken, isTesting, onTestResult]);
 65→
 66→  return (
 67→    <div className="connection-test">
 68→      <button
 69→        type="button"
 70→        className="connection-test-btn"
 71→        onClick={handleTest}
 72→        disabled={isTesting || !endpoint}
 73→      >
 74→        {isTesting ? (
 75→          <>
 76→            {'[--testing...]'}
 77→            <span className="connection-test-spinner" />
 78→          </>
 79→        ) : (
 80→          '[--test connection]'
 81→        )}
 82→      </button>
 83→
 84→      {testResult && (
 85→        <div className="connection-test-result" role="status" aria-live="polite">
 86→          {testResult.success ? (
 87→            <div className="connection-test-success">
 88→              {'> connected ('}
 89→              {testResult.latencyMs}
 90→              {'ms) // detected: '}
 91→              {testResult.protocol}
 92→              {testResult.version ? ` ${testResult.version}` : ''}
 93→            </div>
 94→          ) : (
 95→            <div className="connection-test-error">
 96→              {testResult.error?.includes('authentication') ? (
 97→                <>{`> failed: authentication failed. check your auth token.`}</>
 98→              ) : (
 99→                <>
100→                  {`> failed: ${testResult.error || 'could not detect ipfs protocol at this endpoint.'}`}
101→                </>
102→              )}
103→            </div>
104→          )}
105→        </div>
106→      )}
107→    </div>
108→  );
109→}
110→
111→/**
112→ * Run connection test via TEE worker (server-side, no CORS issues).
113→ *
114→ * 1. ECIES-encrypt { endpoint, authToken } with TEE public key
115→ * 2. POST encrypted config to /tee/connection-test
116→ * 3. TEE decrypts in-enclave, probes endpoint, returns result
117→ */
118→async function teeRoutedTest(
119→  endpoint: string,
120→  authToken: string,
121→  teeKeys: { currentPublicKey: string; currentEpoch: number }
122→): Promise<ConnectionTestResult> {
123→  // Build config JSON and ECIES-encrypt with TEE public key
124→  const configJson = JSON.stringify({ endpoint, authToken: authToken || undefined });
125→  const configBytes = new TextEncoder().encode(configJson);
126→  const teePublicKey = hexToBytes(teeKeys.currentPublicKey);
127→  const encrypted = await wrapKey(configBytes, teePublicKey);
128→  const encryptedHex = bytesToHex(encrypted);
129→
130→  // Call TEE-routed connection test via generated api-client
131→  const response = await teeControllerConnectionTest({
132→    encryptedConfig: encryptedHex,
133→    epoch: teeKeys.currentEpoch,
134→  });
135→
136→  return {
137→    success: response.success,
138→    protocol: response.protocol as ConnectionTestResult['protocol'],
139→    version: response.version,
140→    latencyMs: response.latencyMs,
141→    error: response.error,
142→  };
143→}
