 97→  /**
 98→   * Initialize vault for new users or load existing vault keys.
 99→   * Called after successful backend authentication.
100→   * Uses Core Kit's getVaultKeypair() instead of PnP provider.
101→   *
102→   * Deduplicated at module level: concurrent callers share a single
103→   * in-flight promise to prevent double vault init on page reload.
104→   */
105→  const initializeOrLoadVault = useCallback(async (): Promise<void> => {
106→    if (vaultInitPromise) return vaultInitPromise;
107→    const doInit = async () => {
108→      // Get user's secp256k1 keypair from Core Kit TSS export
109→      const userKeypair = await getVaultKeypair();
110→
111→      if (!userKeypair) {
112→        throw new Error('Failed to get vault keypair from Core Kit');
113→      }
114→
115→      // Store keypair in auth store for crypto operations
116→      setVaultKeypair(userKeypair);
117→
118→      // Isolate getVault() so only its 404 triggers new-user initialization.
119→      // Downstream errors (IPNS resolve, IPFS fetch) must not be misclassified.
120→      let existingVault: Awaited<ReturnType<typeof vaultApi.getVault>> | null = null;
121→      try {
122→        existingVault = await vaultApi.getVault();
123→      } catch (error) {
124→        const is404 = (error as { response?: { status?: number } })?.response?.status === 404;
125→        if (!is404) {
126→          console.error('[useAuth] Failed to load vault:', error);
127→          throw error;
128→        }
129→      }
130→
131→      if (existingVault) {
132→        // Store TEE keys if available
133→        if (existingVault.teeKeys) {
134→          useAuthStore.getState().setTeeKeys(existingVault.teeKeys);
135→        }
136→
137→        // Read rootFolderKey from dedicated vault key IPNS (separate from root folder IPNS)
138→        const vaultKeyKeypair = await deriveVaultKeyIpnsKeypair(userKeypair.privateKey);
139→
140→        const resolved = await resolveIpnsRecord(vaultKeyKeypair.ipnsName);
141→        if (!resolved) throw new Error('Vault key IPNS name not found');
142→
143→        const blobBytes = await fetchFromIpfs(resolved.cid);
144→
145→        if (detectBlobVersion(blobBytes) !== 2) {
146→          throw new Error('Vault key blob is not v2 format');
147→        }
148→
149→        const encKey = deserializeVaultBlobV2(blobBytes);
150→        const rootFolderKey = await unwrapKey(encKey, userKeypair.privateKey);
151→
152→        // Root folder IPNS keypair is the original vault derivation
153→        const rootIpnsKeypair = await deriveVaultIpnsKeypair(userKeypair.privateKey);
154→
155→        setVaultKeys({
156→          rootFolderKey,
157→          rootIpnsKeypair,
158→          rootIpnsName: existingVault.rootIpnsName,
159→          vaultId: existingVault.id,
160→        });
161→      } else {
162→        // New user -- initialize vault with separate key blob + folder metadata
163→        console.log('[Auth] New user -- initializing vault');
164→        const newVault = await initializeVault(userKeypair.privateKey);
165→        const rootIpnsName = await deriveIpnsName(newVault.rootIpnsKeypair.publicKey);
166→
167→        // Derive vault key IPNS keypair (separate from root folder IPNS)
168→        const vaultKeyKeypair = await deriveVaultKeyIpnsKeypair(userKeypair.privateKey);
169→        const vaultKeyIpnsName = vaultKeyKeypair.ipnsName;
170→
171→        // 1. Publish v2 key blob to vault key IPNS (rootFolderKey storage — key only, no metadata)
172→        const encryptedRootFolderKey = await wrapKey(newVault.rootFolderKey, userKeypair.publicKey);
173→        const v2Blob = serializeVaultBlobV2(encryptedRootFolderKey);
174→
175→        const keyBlobUpload = await addToIpfs(new Blob([v2Blob as BlobPart]));
176→        const keyPublishResult = await createAndPublishIpnsRecord({
177→          ipnsPrivateKey: vaultKeyKeypair.privateKey,
178→          ipnsName: vaultKeyIpnsName,
179→          metadataCid: keyBlobUpload.cid,
180→          sequenceNumber: 0n,
181→          expectedSequenceNumber: undefined,
182→        });
183→        if (!keyPublishResult.success) {
184→          throw new Error('Failed to publish vault key blob to IPNS');
185→        }
186→
187→        // 2. Publish folder metadata using v1 encrypted envelope format on IPFS ({iv, data});
188→        //    FolderMetadata.version remains 'v2' (metadata schema version).
189→        const emptyMetadata: FolderMetadata = { version: 'v2', children: [] };
190→        const encrypted = await encryptFolderMetadata(emptyMetadata, newVault.rootFolderKey);
191→        const metadataBlob = new Blob([JSON.stringify(encrypted)], { type: 'application/json' });
192→        const metadataUpload = await addToIpfs(metadataBlob);
193→        const folderPublishResult = await createAndPublishIpnsRecord({
194→          ipnsPrivateKey: newVault.rootIpnsKeypair.privateKey,
195→          ipnsName: rootIpnsName,
196→          metadataCid: metadataUpload.cid,
197→          sequenceNumber: 0n,
198→          expectedSequenceNumber: undefined,
199→        });
200→        if (!folderPublishResult.success) {
201→          throw new Error('Failed to publish initial root folder metadata');
202→        }
203→
204→        // 3. Register vault with API (no crypto fields -- IPFS-only)
205→        const storedVault = await vaultApi.initVault({
206→          ownerPublicKey: bytesToHex(userKeypair.publicKey),
207→          rootIpnsName,
208→        });
209→
210→        if (storedVault.teeKeys) {
211→          useAuthStore.getState().setTeeKeys(storedVault.teeKeys);
212→        }
213→
214→        setVaultKeys({
215→          rootFolderKey: newVault.rootFolderKey,
216→          rootIpnsKeypair: newVault.rootIpnsKeypair,
217→          rootIpnsName,
218→          vaultId: storedVault.id,
219→          isNewVault: true,
220→        });
221→      }
222→
223→      // Load BYO pinning config from encrypted IPNS entry (if configured).
224→      // Gracefully degrades to cipherbox-only mode on any failure.
225→      const loadByoConfig = async (
226→        userPrivateKey: Uint8Array
227→      ): Promise<PinningConfig | undefined> => {
228→        try {
229→          const byoKeypair = await deriveByoConfigIpnsKeypair(userPrivateKey);
230→          const BYO_IPNS_NAME_KEY = 'cipherbox-byo-ipns-name';
231→          const storedIpnsName = localStorage.getItem(BYO_IPNS_NAME_KEY);
232→          const ipnsName = storedIpnsName || byoKeypair.ipnsName;
233→
234→          const resolved = await resolveIpnsRecord(ipnsName);
235→          if (!resolved?.cid) return undefined;
236→
237→          const encrypted = await fetchFromIpfs(resolved.cid);
238→          const plaintext = await unwrapKey(encrypted, userPrivateKey);
239→          let config: ByoIpfsConfig;
240→          try {
241→            const json = new TextDecoder().decode(plaintext);
242→            config = JSON.parse(json) as ByoIpfsConfig;
243→          } finally {
244→            clearBytes(plaintext);
245→          }
246→
247→          // Cache the IPNS name for future lookups
248→          if (!storedIpnsName) {
249→            localStorage.setItem(BYO_IPNS_NAME_KEY, ipnsName);
250→          }
251→
252→          return {
253→            mode: config.pinningMode,
254→            externalProvider: config.externalProvider ?? undefined,
255→          };
256→        } catch {
257→          // No BYO config or decryption failed -- default to cipherbox-only
258→          return undefined;
259→        }
260→      };
261→
262→      // Initialize SDK client with decrypted vault keys
263→      const vaultState = useVaultStore.getState();
264→      const authState = useAuthStore.getState();
265→      if (vaultState.rootFolderKey && vaultState.rootIpnsKeypair && vaultState.rootIpnsName) {
266→        const apiUrl = import.meta.env.VITE_API_URL || window.location.origin + '/api';
267→        const getAccessToken = async () => {
268→          const state = useAuthStore.getState();
269→          return state.accessToken || '';
270→        };
271→
272→        // Load BYO config before initializing SDK client
273→        const pinningConfig = await loadByoConfig(userKeypair.privateKey);
274→
275→        // @cipherbox/api-client is configured in lib/api-config.ts at module load time.
276→
277→        const sdkClient = initSdkClient({
278→          apiUrl,
279→          getAccessToken,
280→          vaultKeypair: {
281→            publicKey: userKeypair.publicKey,
282→            privateKey: userKeypair.privateKey,
283→          },
284→          rootIpnsName: vaultState.rootIpnsName,
285→          rootFolderKey: vaultState.rootFolderKey,
286→          teeKeys: authState.teeKeys ?? undefined,
287→          pinningConfig,
288→          shareCallbacks: {
289→            getCoveringShares: async (folderIpnsName: string) => {
290→              const { findCoveringShares } = await import('../services/share.service');
291→              const folders = useFolderStore.getState().folders;
292→              // Find the folder ID from IPNS name for ancestor traversal
293→              const folderId =
294→                Object.keys(folders).find((id) => folders[id].ipnsName === folderIpnsName) ?? null;
295→              return findCoveringShares(folderIpnsName, folders, folderId);
296→            },
297→            addShareKeys: async (shareId, keys) => {
298→              const { addShareKeys } = await import('../services/share.service');
299→              await addShareKeys(shareId, keys);
300→            },
301→          },
302→        });
303→
304→        // Subscribe folder store to SDK events
305→        useFolderStore.getState().subscribeToSdk(sdkClient);
306→
307→        // Subscribe bin store to SDK events
308→        useBinStore.getState().subscribeToSdk(sdkClient);
309→      }
310→
311→      // Non-blocking device registry initialization (fire-and-forget)
312→      // Placed after vault load so registry failures never block login
313→      void (async () => {
314→        try {
315→          const deviceKeypair = await getOrCreateDeviceIdentity({
316→            mode: 'persisted',
317→            vaultPrivateKey: userKeypair.privateKey,
318→          });
319→          const deviceInfo = detectDeviceInfo();
320→          const result = await initializeOrSyncRegistry({
321→            userPrivateKey: userKeypair.privateKey,
322→            userPublicKey: userKeypair.publicKey,
323→            deviceKeypair,
324→            deviceInfo: { ...deviceInfo, ipHash: '' },
325→          });
326→          if (result) {
327→            useDeviceRegistryStore
328→              .getState()
329→              .setRegistry(result.registry, result.ipnsName, deviceKeypair.deviceId);
330→          }
331→        } catch (error) {
332→          console.error('[Auth] Device registry init failed (non-blocking):', error);
333→        }
334→      })();
335→
336→      // Non-blocking bin initialization (fire-and-forget)
337→      // After old service creates/loads bin, also load into SDK for deleteToBin support
338→      void (async () => {
339→        try {
340→          await initializeBin({
341→            userPrivateKey: userKeypair.privateKey,
342→            userPublicKey: userKeypair.publicKey,
343→          });
344→          // Now load bin into SDK (old service ensures bin IPNS record exists)
345→          const { getSdkClient, hasSdkClient } = await import('../lib/sdk-provider');
346→          if (hasSdkClient()) {
347→            await getSdkClient().loadBin();
348→          }
349→        } catch (error) {
350→          console.error('[Auth] Bin initialization failed (non-blocking):', error);
351→        }
352→      })();
353→
354→      // Non-blocking: fetch retention config from API
355→      void (async () => {
356→        try {
357→          const config = await vaultControllerGetConfig();
358→          if (config.recycleBinRetentionDays != null) {
359→            useBinStore.getState().setRetentionDays(config.recycleBinRetentionDays);
360→          }
361→        } catch (error) {
362→          console.error('[Auth] Failed to fetch vault config (non-blocking):', error);
363→        }
364→      })();
365→    };
366→    vaultInitPromise = doInit().finally(() => {
367→      vaultInitPromise = null;
368→    });
369→    return vaultInitPromise;
370→  }, [getVaultKeypair, setVaultKeypair, setVaultKeys]);
