372→  /**
373→   * Complete backend authentication after Core Kit login.
374→   * Sends the CipherBox-issued JWT (which we used for Core Kit loginWithJWT)
375→   * to the backend with loginType 'corekit'. The backend verifies it against
376→   * its own JWKS since CipherBox is the identity provider.
377→   */
378→  const completeBackendAuth = useCallback(
379→    async (authMethod: string, cipherboxJwt: string): Promise<void> => {
380→      // 1. Get real publicKey from Core Kit TSS export
381→      const publicKey = await getPublicKeyHex();
382→      if (!publicKey) {
383→        throw new Error('Failed to get publicKey from Core Kit');
384→      }
385→
386→      // publicKey available for debugging via DevTools if needed
387→
388→      // 2. Authenticate with CipherBox backend
389→      // Backend verifies our CipherBox JWT and resolves placeholder publicKey
390→      const response = await authApi.login({
391→        idToken: cipherboxJwt,
392→        publicKey,
393→        loginType: 'corekit',
394→      });
395→
396→      // 3. Store access token (refresh token in HTTP-only cookie)
397→      // Note: this does NOT set isAuthenticated — we wait until vault + SDK
398→      // are fully initialized to prevent Login.tsx from redirecting to /files
399→      // before the SDK client is ready for file operations.
400→      setAccessToken(response.accessToken);
401→
402→      // 4. Remember auth method for UX
403→      setLastAuthMethod(authMethod);
404→
405→      // 5. Initialize or load vault + SDK client
406→      await initializeOrLoadVault();
407→
408→      // 6. Now that vault keys are loaded and SDK is initialized,
409→      // mark the user as authenticated. This triggers Login.tsx → /files redirect.
410→      setAuthenticated();
411→    },
412→    [getPublicKeyHex, setAccessToken, setAuthenticated, setLastAuthMethod, initializeOrLoadVault]
413→  );
414→
415→  /**
416→   * Complete the login flow after REQUIRED_SHARE is resolved.
417→   * Called after inputFactorKey() succeeds (from recovery phrase or cross-device approval).
418→   * Uses the stored pendingCipherboxJwt to call completeBackendAuth with the REAL publicKey
419→   * (since Core Kit is now LOGGED_IN), then navigates to /files.
420→   */
421→  const completeRequiredShare = useCallback(async (): Promise<void> => {
422→    // Read directly from Zustand store to get fresh values — this callback
423→    // may be called from useDeviceApproval's useAuth() instance, so we
424→    // can't rely on closure-captured selector values.
425→    const { pendingCipherboxJwt: jwt, pendingAuthMethod: method } = useAuthStore.getState();
426→
427→    if (!jwt || !method) {
428→      throw new Error('No pending auth info for REQUIRED_SHARE completion');
429→    }
430→
431→    // Core Kit should now be LOGGED_IN after inputFactorKey()
432→    // Complete backend auth with the REAL publicKey (replaces the placeholder session)
433→    await completeBackendAuth(method, jwt);
434→
435→    // NOW sync Core Kit React state to LOGGED_IN.
436→    // We deliberately delayed this from inputFactorKey() to prevent the session
437→    // restoration effect from firing before backend auth completed.
438→    // At this point isAuthenticated is true (from completeBackendAuth -> setAuthenticated),
439→    // so the session restore guard (coreKitLoggedIn && !isAuthenticated) won't trigger.
440→    syncStatus();
441→
442→    // Clear pending state
443→    setPendingAuth(null, null);
444→
445→    // Navigate to files
446→    navigate('/files');
447→  }, [completeBackendAuth, syncStatus, setPendingAuth, navigate]);
