  1→/**
  2→ * SDK Provider - CipherBoxClient lifecycle management
  3→ *
  4→ * Manages a singleton CipherBoxClient instance for the web app.
  5→ * Created after vault load (login complete), destroyed on logout.
  6→ *
  7→ * The SDK client is the single source of truth for all file operations.
  8→ * Hooks call client methods, and stores subscribe to client events.
  9→ */
 10→import { CipherBoxClient, type CipherBoxClientConfig } from '@cipherbox/sdk';
 11→import type { PinningConfig } from '@cipherbox/sdk';
 12→import { apiAxios } from './api-config';
 13→import type { FolderNode } from '../stores/folder.store';
 14→
 15→let _client: CipherBoxClient | null = null;
 16→let _lastConfig: CipherBoxClientConfig | null = null;
 17→
 18→/**
 19→ * Initialize the SDK client. Called after vault is loaded (login complete).
 20→ * The client persists for the session and is destroyed on logout.
 21→ *
 22→ * If a client already exists (e.g., session restoration), it is destroyed
 23→ * before creating the new one.
 24→ */
 25→export function initSdkClient(config: CipherBoxClientConfig): CipherBoxClient {
 26→  if (_client) {
 27→    _client.destroy();
 28→  }
 29→  // Inject the shared axios instance so CipherBoxClient uses the same
 30→  // instance as orval-generated functions (single instance, no dual path).
 31→  _lastConfig = { ...config };
 32→  _client = new CipherBoxClient({ ...config, axiosInstance: apiAxios });
 33→  return _client;
 34→}
 35→
 36→/**
 37→ * Get the current SDK client instance.
 38→ * Throws if called before initSdkClient() (i.e., before login).
 39→ */
 40→export function getSdkClient(): CipherBoxClient {
 41→  if (!_client) {
 42→    throw new Error('SDK client not initialized. Call initSdkClient() after login.');
 43→  }
 44→  return _client;
 45→}
 46→
 47→/**
 48→ * Check if the SDK client is initialized (for conditional usage).
 49→ */
 50→export function hasSdkClient(): boolean {
 51→  return _client !== null;
 52→}
 53→
 54→/**
 55→ * Destroy the SDK client. Called on logout.
 56→ * Clears internal state, key caches, and event subscriptions.
 57→ */
 58→export function destroySdkClient(): void {
 59→  if (_client) {
 60→    _client.destroy();
 61→    _client = null;
 62→  }
 63→  _lastConfig = null;
 64→}
 65→
 66→/**
 67→ * Reconfigure the SDK client's pinning config at runtime.
 68→ * Called from StorageTab after saving new BYO settings.
 69→ *
 70→ * Destroys the current client and recreates it with updated pinningConfig
 71→ * while preserving all other configuration. This is acceptable since config
 72→ * changes are infrequent (only on Settings save).
 73→ */
 74→export function reconfigurePinning(pinningConfig?: PinningConfig): void {
 75→  if (!_client || !_lastConfig) return;
 76→  _client.destroy();
 77→  _lastConfig = { ..._lastConfig, pinningConfig };
 78→  _client = new CipherBoxClient({ ..._lastConfig, axiosInstance: apiAxios });
 79→}
 80→
 81→/**
 82→ * Ensure a folder from the Zustand store is registered in the SDK's
 83→ * internal FolderTree. This bridges the gap between folder navigation
 84→ * (which loads folders into Zustand) and SDK operations (which require
 85→ * folders in the SDK's internal state).
 86→ *
 87→ * Only registers if the SDK doesn't already have the folder. The SDK's
 88→ * internal state (sequence number, children, keys) is authoritative once
 89→ * a folder is registered — all mutations go through the SDK.
 90→ */
 91→export function ensureFolderRegistered(folder: FolderNode): void {
 92→  const client = getSdkClient();
 93→
 94→  // Don't overwrite if SDK already has this folder — its internal state
 95→  // is authoritative (correct sequence number, keys, children from mutations)
 96→  if (client.hasFolder(folder.ipnsName)) return;
 97→
 98→  // Guard: don't register placeholder folders with empty key material —
 99→  // would cause crypto/IPNS errors on subsequent mutations
100→  if (folder.folderKey.length === 0 || folder.ipnsPrivateKey.length === 0) {
101→    return;
102→  }
103→
104→  client.registerFolder(
105→    folder.ipnsName,
106→    folder.folderKey,
107→    {
108→      publicKey: new Uint8Array(0), // Public key derived from private key when needed
109→      privateKey: folder.ipnsPrivateKey,
110→    },
111→    folder.children,
112→    folder.sequenceNumber
113→  );
114→}
