  1→import { Injectable, Logger } from '@nestjs/common';
  2→import { ConfigService } from '@nestjs/config';
  3→import { TeeKeyStateService } from './tee-key-state.service';
  4→import type { ConnectionTestResponseDto } from './dto/connection-test.dto';
  5→
  6→/**
  7→ * A single entry in a batch republish request to the TEE worker.
  8→ */
  9→export interface RepublishEntry {
 10→  /** Base64-encoded ECIES-encrypted IPNS Ed25519 private key */
 11→  encryptedIpnsKey: string;
 12→  /** TEE key epoch the IPNS key was encrypted for */
 13→  keyEpoch: number;
 14→  /** IPNS name (k51... or bafzaa...) */
 15→  ipnsName: string;
 16→  /** CID of the latest encrypted folder metadata */
 17→  latestCid: string;
 18→  /** Current IPNS sequence number (bigint as string) */
 19→  sequenceNumber: string;
 20→  /** Current active TEE epoch */
 21→  currentEpoch: number;
 22→  /** Previous TEE epoch (null if no grace period active) */
 23→  previousEpoch: number | null;
 24→}
 25→
 26→/**
 27→ * Result for a single entry in a batch republish response from the TEE worker.
 28→ */
 29→export interface RepublishResult {
 30→  /** IPNS name this result corresponds to */
 31→  ipnsName: string;
 32→  /** Whether the signing succeeded */
 33→  success: boolean;
 34→  /** Base64-encoded signed IPNS record (present on success) */
 35→  signedRecord?: string;
 36→  /** New sequence number after signing (present on success) */
 37→  newSequenceNumber?: string;
 38→  /** Base64-encoded re-encrypted IPNS key if epoch was upgraded (present if key epoch changed) */
 39→  upgradedEncryptedKey?: string;
 40→  /** New key epoch if the key was re-encrypted (present if key epoch changed) */
 41→  upgradedKeyEpoch?: number;
 42→  /** Error message (present on failure) */
 43→  error?: string;
 44→}
 45→
 46→/** Default timeout for TEE worker HTTP requests (30 seconds) */
 47→const TEE_REQUEST_TIMEOUT_MS = 30_000;
 48→
 49→@Injectable()
 50→export class TeeService {
 51→  private readonly logger = new Logger(TeeService.name);
 52→  private readonly teeWorkerUrl: string;
 53→  private readonly teeWorkerSecret: string;
 54→
 55→  constructor(
 56→    private readonly configService: ConfigService,
 57→    private readonly teeKeyStateService: TeeKeyStateService
 58→  ) {
 59→    this.teeWorkerUrl = this.configService.get<string>('TEE_WORKER_URL', 'http://localhost:3001');
 60→    this.teeWorkerSecret = this.configService.get<string>('TEE_WORKER_SECRET', '');
 61→  }
 62→
 63→  /**
 64→   * Check TEE worker health and get current epoch.
 65→   */
 66→  async getHealth(): Promise<{ healthy: boolean; epoch: number }> {
 67→    const response = await this.fetchWithTimeout(`${this.teeWorkerUrl}/health`, {
 68→      method: 'GET',
 69→      headers: this.authHeaders(),
 70→    });
 71→
 72→    if (!response.ok) {
 73→      throw new Error(`TEE worker health check failed: HTTP ${response.status}`);
 74→    }
 75→
 76→    const data = (await response.json()) as { healthy: boolean; epoch: number };
 77→    return data;
 78→  }
 79→
 80→  /**
 81→   * Get the TEE worker's public key for a specific epoch.
 82→   * Returns the 65-byte uncompressed secp256k1 public key.
 83→   */
 84→  async getPublicKey(epoch: number): Promise<Uint8Array> {
 85→    const response = await this.fetchWithTimeout(`${this.teeWorkerUrl}/public-key?epoch=${epoch}`, {
 86→      method: 'GET',
 87→      headers: this.authHeaders(),
 88→    });
 89→
 90→    if (!response.ok) {
 91→      throw new Error(`TEE worker public key request failed: HTTP ${response.status}`);
 92→    }
 93→
 94→    const data = (await response.json()) as { publicKey: string };
 95→    const publicKeyBytes = new Uint8Array(Buffer.from(data.publicKey, 'hex'));
 96→
 97→    if (publicKeyBytes.length !== 65 || publicKeyBytes[0] !== 0x04) {
 98→      throw new Error(
 99→        `Invalid TEE public key: expected 65 bytes with 0x04 prefix, got ${publicKeyBytes.length} bytes`
100→      );
101→    }
102→
103→    return publicKeyBytes;
104→  }
105→
106→  /**
107→   * Send a batch of entries to the TEE worker for IPNS record signing.
108→   * The TEE worker decrypts IPNS keys, signs new records, and returns results.
109→   */
110→  async republish(entries: RepublishEntry[]): Promise<RepublishResult[]> {
111→    this.logger.log(`Sending ${entries.length} entries to TEE worker for republishing`);
112→
113→    const response = await this.fetchWithTimeout(`${this.teeWorkerUrl}/republish`, {
114→      method: 'POST',
115→      headers: {
116→        ...this.authHeaders(),
117→        'Content-Type': 'application/json',
118→      },
119→      body: JSON.stringify({ entries }),
120→    });
121→
122→    if (!response.ok) {
123→      throw new Error(`TEE worker republish failed: HTTP ${response.status}`);
124→    }
125→
126→    const data = (await response.json()) as { results: RepublishResult[] };
127→    const successCount = data.results.filter((r) => r.success).length;
128→    this.logger.log(
129→      `TEE republish complete: ${successCount}/${data.results.length} entries succeeded`
130→    );
131→
132→    return data.results;
133→  }
134→
135→  /**
136→   * Initialize TEE key state from the TEE worker on module startup.
137→   * If tee_key_state is empty, queries TEE for epoch 1 public key and initializes.
138→   * If tee_key_state has data, validates it still matches the TEE worker.
139→   * Gracefully handles TEE worker being unavailable (logs warning, does not throw).
140→   */
141→  async initializeFromTee(): Promise<void> {
142→    try {
143→      // Check TEE worker health first
144→      const health = await this.getHealth();
145→      this.logger.log(`TEE worker healthy, current epoch: ${health.epoch}`);
146→
147→      const currentState = await this.teeKeyStateService.getCurrentState();
148→
149→      if (!currentState) {
150→        // First boot: initialize from TEE worker
151→        const publicKey = await this.getPublicKey(health.epoch);
152→        await this.teeKeyStateService.initializeEpoch(health.epoch, publicKey);
153→        this.logger.log(`TEE key state initialized from worker at epoch ${health.epoch}`);
154→        return;
155→      }
156→
157→      // Validate existing state matches TEE worker
158→      if (currentState.currentEpoch !== health.epoch) {
159→        this.logger.warn(
160→          `TEE epoch mismatch: DB has epoch ${currentState.currentEpoch}, TEE worker reports epoch ${health.epoch}. ` +
161→            'This may indicate a TEE worker update. Manual epoch rotation may be needed.'
162→        );
163→      } else {
164→        this.logger.log(
165→          `TEE key state validated: epoch ${currentState.currentEpoch} matches worker`
166→        );
167→      }
168→    } catch (error) {
169→      // TEE worker unavailable - this is expected during development
170→      // and acceptable for startup (republishing will retry later)
171→      const message = error instanceof Error ? error.message : String(error);
172→      this.logger.warn(`TEE worker unavailable during initialization: ${message}`);
173→      this.logger.warn(
174→        'TEE republishing will not work until the TEE worker is available. ' +
175→          'This is expected in development without a TEE simulator.'
176→      );
177→    }
178→  }
179→
180→  /**
181→   * Forward a connection test to the TEE worker.
182→   * The TEE worker decrypts ECIES-encrypted provider config in-enclave,
183→   * probes the endpoint server-side, and returns the result.
184→   */
185→  async connectionTest(encryptedConfig: string, epoch: number): Promise<ConnectionTestResponseDto> {
186→    const response = await this.fetchWithTimeout(`${this.teeWorkerUrl}/connection-test`, {
187→      method: 'POST',
188→      headers: {
189→        ...this.authHeaders(),
190→        'Content-Type': 'application/json',
191→      },
192→      body: JSON.stringify({ encryptedConfig, epoch }),
193→    });
194→
195→    if (!response.ok) {
196→      const errorText = await response.text();
197→      return {
198→        success: false,
199→        latencyMs: 0,
200→        error: `TEE worker error: ${response.status} - ${errorText}`,
201→      };
202→    }
203→
204→    return (await response.json()) as ConnectionTestResponseDto;
205→  }
206→
207→  /**
208→   * Build authorization headers for TEE worker requests.
209→   * IMPORTANT: Never log the secret value.
210→   */
211→  private authHeaders(): Record<string, string> {
212→    const headers: Record<string, string> = {};
213→    if (this.teeWorkerSecret) {
214→      headers['Authorization'] = `Bearer ${this.teeWorkerSecret}`;
215→    }
216→    return headers;
217→  }
218→
219→  /**
220→   * Fetch with a timeout to prevent hanging requests.
221→   */
222→  private async fetchWithTimeout(url: string, init: RequestInit): Promise<Response> {
223→    const controller = new AbortController();
224→    const timeout = setTimeout(() => controller.abort(), TEE_REQUEST_TIMEOUT_MS);
225→
226→    try {
227→      return await fetch(url, {
228→        ...init,
229→        signal: controller.signal,
230→      });
231→    } catch (error) {
232→      if (error instanceof Error && error.name === 'AbortError') {
233→        throw new Error(`TEE worker request timed out after ${TEE_REQUEST_TIMEOUT_MS}ms: ${url}`);
234→      }
235→      throw error;
236→    } finally {
237→      clearTimeout(timeout);
238→    }
239→  }
240→}
241→

  1→import { Processor, WorkerHost } from '@nestjs/bullmq';
  2→import { Logger } from '@nestjs/common';
  3→import { InjectRepository } from '@nestjs/typeorm';
  4→import { ConfigService } from '@nestjs/config';
  5→import { Repository } from 'typeorm';
  6→import { Job } from 'bullmq';
  7→import { PinMigration } from './migration.entity';
  8→import { PinnedCid } from '../vault/entities/pinned-cid.entity';
  9→import { MigrationService } from './migration.service';
 10→
 11→const BATCH_SIZE = 10;
 12→
 13→@Processor('pin-migration')
 14→export class MigrationProcessor extends WorkerHost {
 15→  private readonly logger = new Logger(MigrationProcessor.name);
 16→
 17→  constructor(
 18→    @InjectRepository(PinMigration)
 19→    private readonly migrationRepo: Repository<PinMigration>,
 20→    @InjectRepository(PinnedCid)
 21→    private readonly pinnedCidRepo: Repository<PinnedCid>,
 22→    private readonly migrationService: MigrationService,
 23→    private readonly configService: ConfigService
 24→  ) {
 25→    super();
 26→  }
 27→
 28→  async process(job: Job<{ migrationId: string }>): Promise<void> {
 29→    const { migrationId } = job.data;
 30→
 31→    const migration = await this.migrationRepo.findOneOrFail({
 32→      where: { id: migrationId },
 33→    });
 34→
 35→    // Mark as running
 36→    if (migration.status === 'pending') {
 37→      await this.migrationRepo.update(migrationId, { status: 'running' });
 38→    }
 39→
 40→    // Get all CIDs for user
 41→    const pinnedCids = await this.pinnedCidRepo.find({
 42→      where: { userId: migration.userId },
 43→    });
 44→
 45→    const TEE_URL = this.configService.get<string>('TEE_WORKER_URL');
 46→    const TEE_SECRET = this.configService.get<string>('TEE_WORKER_SECRET');
 47→
 48→    if (!TEE_URL || !TEE_SECRET) {
 49→      this.logger.error('TEE_WORKER_URL or TEE_WORKER_SECRET not configured');
 50→      await this.migrationRepo.update(migrationId, { status: 'failed' });
 51→      return;
 52→    }
 53→
 54→    this.logger.log(
 55→      `Processing migration ${migrationId}: ${pinnedCids.length} CIDs in batches of ${BATCH_SIZE}`
 56→    );
 57→
 58→    for (let i = 0; i < pinnedCids.length; i += BATCH_SIZE) {
 59→      // Check if paused or cancelled before processing each batch
 60→      const current = await this.migrationRepo.findOneOrFail({
 61→        where: { id: migrationId },
 62→      });
 63→      if (current.status === 'paused' || current.status === 'cancelled') {
 64→        this.logger.log(`Migration ${migrationId} ${current.status} -- stopping processing`);
 65→        break;
 66→      }
 67→
 68→      const batch = pinnedCids.slice(i, i + BATCH_SIZE);
 69→      const cids = batch.map((p) => p.cid);
 70→
 71→      try {
 72→        const response = await fetch(`${TEE_URL}/migrate`, {
 73→          method: 'POST',
 74→          headers: {
 75→            'Content-Type': 'application/json',
 76→            Authorization: `Bearer ${TEE_SECRET}`,
 77→          },
 78→          body: JSON.stringify({
 79→            cids,
 80→            sourceConfigEncrypted: migration.sourceConfigEncrypted,
 81→            destConfigEncrypted: migration.destConfigEncrypted,
 82→          }),
 83→        });
 84→
 85→        if (!response.ok) {
 86→          const text = await response.text();
 87→
 88→          // Handle 401 specifically (token expired or invalid TEE auth)
 89→          if (response.status === 401) {
 90→            await this.migrationService.updateProgress(migrationId, 0, cids.length, cids);
 91→            await this.migrationRepo.update(migrationId, { status: 'paused' });
 92→            this.logger.warn(`Migration ${migrationId} paused due to TEE auth failure (401)`);
 93→            return;
 94→          }
 95→
 96→          throw new Error(`TEE migration failed: ${response.status} ${text}`);
 97→        }
 98→
 99→        const result = (await response.json()) as {
100→          succeeded?: string[];
101→          failed?: string[];
102→        };
103→
104→        await this.migrationService.updateProgress(
105→          migrationId,
106→          result.succeeded?.length ?? 0,
107→          result.failed?.length ?? 0,
108→          result.failed
109→        );
110→      } catch (err) {
111→        const message = err instanceof Error ? err.message : String(err);
112→        this.logger.error(`Migration ${migrationId} batch error at offset ${i}: ${message}`);
113→        await this.migrationService.updateProgress(migrationId, 0, cids.length, cids);
114→      }
115→    }
116→
117→    // Mark complete if still running
118→    const final = await this.migrationRepo.findOneOrFail({
119→      where: { id: migrationId },
120→    });
121→    if (final.status === 'running') {
122→      await this.migrationRepo.update(migrationId, {
123→        status: 'completed',
124→        completedAt: new Date(),
125→      });
126→      this.logger.log(`Migration ${migrationId} completed`);
127→    }
128→  }
129→}
