  1→import {
  2→  Injectable,
  3→  Logger,
  4→  ConflictException,
  5→  NotFoundException,
  6→  ForbiddenException,
  7→} from '@nestjs/common';
  8→import { InjectRepository } from '@nestjs/typeorm';
  9→import { InjectQueue } from '@nestjs/bullmq';
 10→import { Repository, In } from 'typeorm';
 11→import { Queue } from 'bullmq';
 12→import { PinMigration, MigrationStatus } from './migration.entity';
 13→import { PinnedCid } from '../vault/entities/pinned-cid.entity';
 14→import { StartMigrationDto } from './dto/start-migration.dto';
 15→import { MigrationStatusDto } from './dto/migration-status.dto';
 16→
 17→@Injectable()
 18→export class MigrationService {
 19→  private readonly logger = new Logger(MigrationService.name);
 20→
 21→  constructor(
 22→    @InjectRepository(PinMigration)
 23→    private readonly migrationRepo: Repository<PinMigration>,
 24→    @InjectRepository(PinnedCid)
 25→    private readonly pinnedCidRepo: Repository<PinnedCid>,
 26→    @InjectQueue('pin-migration')
 27→    private readonly migrationQueue: Queue
 28→  ) {}
 29→
 30→  /**
 31→   * Start a new pin migration for a user.
 32→   * Prevents concurrent migrations (only one active migration at a time).
 33→   */
 34→  async startMigration(userId: string, dto: StartMigrationDto): Promise<string> {
 35→    // Check for existing active migration
 36→    const activeMigration = await this.migrationRepo.findOne({
 37→      where: {
 38→        userId,
 39→        status: In(['pending', 'running', 'paused'] as MigrationStatus[]),
 40→      },
 41→    });
 42→
 43→    if (activeMigration) {
 44→      throw new ConflictException(
 45→        'An active migration already exists. Complete or cancel it before starting a new one.'
 46→      );
 47→    }
 48→
 49→    // Count pinned CIDs for this user
 50→    const totalCids = await this.pinnedCidRepo.count({ where: { userId } });
 51→
 52→    // Create migration entity
 53→    const migration = this.migrationRepo.create({
 54→      userId,
 55→      status: 'pending' as MigrationStatus,
 56→      totalCids,
 57→      migratedCids: 0,
 58→      failedCids: 0,
 59→      sourceConfigEncrypted: dto.sourceConfigEncrypted,
 60→      destConfigEncrypted: dto.destConfigEncrypted,
 61→      failedCidList: null,
 62→      completedAt: null,
 63→    });
 64→
 65→    const saved = await this.migrationRepo.save(migration);
 66→
 67→    // Enqueue BullMQ job
 68→    await this.migrationQueue.add('pin-migration', { migrationId: saved.id });
 69→
 70→    this.logger.log(`Migration ${saved.id} started for user ${userId} with ${totalCids} CIDs`);
 71→
 72→    return saved.id;
 73→  }
 74→
 75→  /**
 76→   * Get the latest migration status for a user.
 77→   */
 78→  async getStatus(userId: string): Promise<MigrationStatusDto | null> {
 79→    const migration = await this.migrationRepo.findOne({
 80→      where: { userId },
 81→      order: { createdAt: 'DESC' },
 82→    });
 83→
 84→    if (!migration) {
 85→      return null;
 86→    }
 87→
 88→    return {
 89→      id: migration.id,
 90→      status: migration.status,
 91→      totalCids: migration.totalCids,
 92→      migratedCids: migration.migratedCids,
 93→      failedCids: migration.failedCids,
 94→      createdAt: migration.createdAt.toISOString(),
 95→      completedAt: migration.completedAt?.toISOString() ?? null,
 96→    };
 97→  }
 98→
 99→  /**
100→   * Pause an active migration.
101→   * The BullMQ processor checks status before processing each batch.
102→   */
103→  async pauseMigration(userId: string, migrationId: string): Promise<void> {
104→    const migration = await this.findUserMigration(userId, migrationId);
105→
106→    if (migration.status !== 'running' && migration.status !== 'pending') {
107→      throw new ConflictException(`Cannot pause migration in '${migration.status}' status`);
108→    }
109→
110→    await this.migrationRepo.update(migrationId, {
111→      status: 'paused' as MigrationStatus,
112→    });
113→
114→    this.logger.log(`Migration ${migrationId} paused`);
115→  }
116→
117→  /**
118→   * Resume a paused migration.
119→   */
120→  async resumeMigration(userId: string, migrationId: string): Promise<void> {
121→    const migration = await this.findUserMigration(userId, migrationId);
122→
123→    if (migration.status !== 'paused') {
124→      throw new ConflictException(`Cannot resume migration in '${migration.status}' status`);
125→    }
126→
127→    await this.migrationRepo.update(migrationId, {
128→      status: 'running' as MigrationStatus,
129→    });
130→
131→    // Re-enqueue job to continue processing
132→    await this.migrationQueue.add('pin-migration', { migrationId });
133→
134→    this.logger.log(`Migration ${migrationId} resumed`);
135→  }
136→
137→  /**
138→   * Cancel a migration.
139→   */
140→  async cancelMigration(userId: string, migrationId: string): Promise<void> {
141→    const migration = await this.findUserMigration(userId, migrationId);
142→
143→    if (migration.status === 'completed' || migration.status === 'cancelled') {
144→      throw new ConflictException(`Cannot cancel migration in '${migration.status}' status`);
145→    }
146→
147→    await this.migrationRepo.update(migrationId, {
148→      status: 'cancelled' as MigrationStatus,
149→    });
150→
151→    this.logger.log(`Migration ${migrationId} cancelled`);
152→  }
153→
154→  /**
155→   * Update migration progress counters.
156→   * Called by the BullMQ processor after each batch.
157→   */
158→  async updateProgress(
159→    migrationId: string,
160→    migratedDelta: number,
161→    failedDelta: number,
162→    failedCids?: string[]
163→  ): Promise<void> {
164→    const migration = await this.migrationRepo.findOneOrFail({
165→      where: { id: migrationId },
166→    });
167→
168→    migration.migratedCids += migratedDelta;
169→    migration.failedCids += failedDelta;
170→
171→    if (failedCids && failedCids.length > 0) {
172→      const existingList = migration.failedCidList ? migration.failedCidList.split(',') : [];
173→      existingList.push(...failedCids);
174→      migration.failedCidList = existingList.join(',');
175→    }
176→
177→    await this.migrationRepo.save(migration);
178→  }
179→
180→  /**
181→   * Find a migration belonging to a specific user.
182→   * Throws NotFoundException if not found, ForbiddenException if wrong user.
183→   */
184→  private async findUserMigration(userId: string, migrationId: string): Promise<PinMigration> {
185→    const migration = await this.migrationRepo.findOne({
186→      where: { id: migrationId },
187→    });
188→
189→    if (!migration) {
190→      throw new NotFoundException(`Migration ${migrationId} not found`);
191→    }
192→
193→    if (migration.userId !== userId) {
194→      throw new ForbiddenException('Migration does not belong to this user');
195→    }
196→
197→    return migration;
198→  }
199→}
