  2→ * @cipherbox/sdk - Type definitions
  3→ *
  4→ * Client configuration and internal state types for the SDK.
  5→ * These types define the contract between the SDK and its consumers.
  6→ */
  7→
  8→import type { TeeKeys, PinningMode, ExternalProviderConfig } from '@cipherbox/sdk-core';
  9→import type { AxiosInstance } from '@cipherbox/api-client';
 10→import type { FolderChild, FolderMetadata } from '@cipherbox/core';
 11→import type { SentShareInfo } from './share';
 12→
 13→/**
 14→ * Pinning configuration for BYO-IPFS support.
 15→ * When absent, defaults to cipherbox-only mode.
 16→ */
 17→export type PinningConfig = {
 18→  mode: PinningMode;
 19→  externalProvider?: ExternalProviderConfig;
 20→};
 21→
 22→/**
 23→ * Callbacks for share-aware key re-wrapping.
 24→ *
 25→ * The SDK uses these to discover active shares and store re-wrapped keys
 26→ * without taking a direct dependency on the shares API or stores.
 27→ */
 28→export type ShareCallbacks = {
 29→  /** Find active shares covering a folder (including ancestor shares). */
 30→  getCoveringShares: (folderIpnsName: string) => Promise<SentShareInfo[]>;
 31→  /** Store re-wrapped keys for a share via the API. */
 32→  addShareKeys: (
 33→    shareId: string,
 34→    keys: Array<{ keyType: 'file' | 'folder'; itemId: string; encryptedKey: string }>
 35→  ) => Promise<void>;
 36→};
 37→
 38→/**
 39→ * Configuration for initializing a CipherBoxClient instance.
 40→ *
 41→ * Consumers provide authentication, keypair, and root folder details.
 42→ * The SDK manages everything else internally.
 43→ */
 44→export type CipherBoxClientConfig = {
 45→  /** Base URL for the CipherBox API (e.g., "https://api.cipherbox.cc") */
 46→  apiUrl: string;
 47→  /** Returns a valid access token. Consumer owns refresh logic. */
 48→  getAccessToken: () => Promise<string>;
 49→  /** User's vault keypair (secp256k1). Used for ECIES operations. */
 50→  vaultKeypair: { publicKey: Uint8Array; privateKey: Uint8Array };
 51→  /** Root folder IPNS name (k51.../bafzaa...) */
 52→  rootIpnsName: string;
 53→  /** Root folder key (AES-256, decrypted on login) */
 54→  rootFolderKey: Uint8Array;
 55→  /** TEE keys for IPNS key wrapping */
 56→  teeKeys?: TeeKeys;
 57→  /**
 58→   * Callbacks for share-aware operations (re-wrapping).
 59→   *
 60→   * When provided, the SDK will automatically re-wrap file and folder keys
 61→   * for share recipients after uploadFile() and createFolder(). This ensures
 62→   * recipients can decrypt items added to shared folders after the share
 63→   * was created.
 64→   *
 65→   * If not provided, re-wrapping is skipped (consumer must handle it).
 66→   */
 67→  shareCallbacks?: ShareCallbacks;
 68→  /** Callback when an operation starts */
 69→  onOperationStart?: (operation: string) => void;
 70→  /** Callback when an operation completes */
 71→  onOperationEnd?: (operation: string) => void;
 72→  /** Callback when an error occurs */
 73→  onError?: (error: Error) => void;
 74→  /** Extra headers sent with every request (e.g., throttle bypass for testing). */
 75→  defaultHeaders?: Record<string, string>;
 76→  /**
 77→   * Pre-built axios instance to use for all API calls.
 78→   * When provided, the client uses this instead of creating its own instance.
 79→   * Use this to share a single instance with the orval singleton (web app)
 80→   * or to inject a fully-configured instance with 401 refresh logic.
 81→   */
 82→  axiosInstance?: AxiosInstance;
 83→  /**
 84→   * BYO-IPFS pinning configuration.
 85→   * When omitted, all pins go through CipherBox infrastructure (default).
 86→   */
 87→  pinningConfig?: PinningConfig;
 88→};
 89→
 90→/**
 91→ * Internal state for a loaded folder.
 92→ *
 93→ * Tracks everything needed to read and update a folder's metadata.
 94→ * This is SDK-internal state -- consumers receive simplified events.
 95→ */
 96→export type FolderState = {
 97→  /** IPNS name identifying this folder */
 98→  ipnsName: string;
 99→  /** Decrypted AES-256 folder key */
100→  folderKey: Uint8Array;
101→  /** Ed25519 IPNS keypair for signing updates */
102→  ipnsKeypair: { publicKey: Uint8Array; privateKey: Uint8Array };
103→  /** Current IPNS sequence number (monotonically increasing) */
104→  sequenceNumber: bigint;
105→  /** Current folder children (files and subfolders) */
106→  children: FolderChild[];
107→  /** Full decrypted folder metadata, or null if not yet loaded */
108→  metadata: FolderMetadata | null;
109→  /** Timestamp (ms) of last successful load from IPNS */
110→  lastLoadedAt: number;
111→};
