 1→/**
 2→ * @cipherbox/crypto - HKDF Key Derivation
 3→ *
 4→ * HKDF-SHA256 key derivation using Web Crypto API.
 5→ * Used for deriving context-specific keys from master key material.
 6→ */
 7→
 8→import { CryptoError } from '../types';
 9→import { AES_KEY_SIZE } from '../constants';
10→
11→/**
12→ * Parameters for HKDF key derivation.
13→ */
14→export type DeriveKeyParams = {
15→  /** Input key material (e.g., master key, signature) */
16→  inputKey: Uint8Array;
17→  /** Salt for HKDF (domain separation) */
18→  salt: Uint8Array;
19→  /** Info/context for HKDF (additional context) */
20→  info: Uint8Array;
21→  /** Output length in bytes (defaults to 32) */
22→  outputLength?: number;
23→};
24→
25→/**
26→ * Derive a key using HKDF-SHA256.
27→ *
28→ * @param params - Derivation parameters
29→ * @returns Derived key bytes
30→ * @throws CryptoError if derivation fails
31→ *
32→ * @example
33→ * ```typescript
34→ * const derivedKey = await deriveKey({
35→ *   inputKey: masterKey,
36→ *   salt: new TextEncoder().encode('CipherBox-v1'),
37→ *   info: new TextEncoder().encode('folder-key'),
38→ *   outputLength: 32
39→ * });
40→ * ```
41→ */
42→export async function deriveKey(params: DeriveKeyParams): Promise<Uint8Array> {
43→  const { inputKey, salt, info, outputLength = AES_KEY_SIZE } = params;
44→
45→  try {
46→    // Copy Uint8Arrays to ensure we have proper ArrayBuffers (not SharedArrayBuffer)
47→    // This also handles any potential offset issues from TypedArray subviews
48→    const inputKeyBuffer = new Uint8Array(inputKey).buffer as ArrayBuffer;
49→    const saltBuffer = new Uint8Array(salt).buffer as ArrayBuffer;
50→    const infoBuffer = new Uint8Array(info).buffer as ArrayBuffer;
51→
52→    // Import input key as raw key material for HKDF
53→    const keyMaterial = await crypto.subtle.importKey(
54→      'raw',
55→      inputKeyBuffer,
56→      'HKDF',
57→      false, // not extractable
58→      ['deriveBits']
59→    );
60→
61→    // Derive key using HKDF-SHA256
62→    const derivedBits = await crypto.subtle.deriveBits(
63→      {
64→        name: 'HKDF',
65→        hash: 'SHA-256',
66→        salt: saltBuffer,
67→        info: infoBuffer,
68→      },
69→      keyMaterial,
70→      outputLength * 8 // deriveBits takes length in bits
71→    );
72→
73→    return new Uint8Array(derivedBits);
74→  } catch {
75→    // Generic error to prevent information leakage
76→    throw new CryptoError('Key derivation failed', 'ENCRYPTION_FAILED');
77→  }
78→}
