 1→/**
 2→ * TEE Key Derivation Service
 3→ *
 4→ * Derives deterministic secp256k1 keypairs per epoch.
 5→ * - Simulator mode: HKDF-SHA256 from a fixed seed (development/testing)
 6→ * - CVM mode: DstackClient.getKey() for hardware-backed derivation (production)
 7→ */
 8→
 9→import { hkdf } from '@noble/hashes/hkdf';
10→import { sha256 } from '@noble/hashes/sha256';
11→import * as secp from '@noble/secp256k1';
12→
13→/** Cache public keys per epoch to avoid repeated derivation */
14→const publicKeyCache = new Map<number, Uint8Array>();
15→
16→/**
17→ * Derive a deterministic secp256k1 keypair for a given epoch.
18→ *
19→ * In simulator mode, uses HKDF-SHA256 with a fixed seed.
20→ * In CVM mode, uses Phala dstack SDK for hardware-backed derivation.
21→ *
22→ * @param epoch - The key epoch number
23→ * @returns Object with publicKey (65 bytes, uncompressed) and privateKey (32 bytes)
24→ */
25→export async function getKeypair(
26→  epoch: number
27→): Promise<{ publicKey: Uint8Array; privateKey: Uint8Array }> {
28→  const mode = process.env.TEE_MODE || 'simulator';
29→
30→  const env = process.env.CIPHERBOX_ENVIRONMENT;
31→  if (
32→    mode === 'simulator' &&
33→    (env === 'production' || (!env && process.env.NODE_ENV === 'production'))
34→  ) {
35→    throw new Error(
36→      'TEE_MODE=simulator is not allowed in production. Set TEE_MODE=cvm for production deployments, or set CIPHERBOX_ENVIRONMENT explicitly.'
37→    );
38→  }
39→
40→  let privateKey: Uint8Array;
41→
42→  if (mode === 'cvm') {
43→    // Production: Phala Cloud CVM with dstack SDK
44→    // Dynamic import -- @phala/dstack-sdk is only available inside CVM
45→    const { DstackClient } = await import('@phala/dstack-sdk');
46→    const client = new DstackClient();
47→    const keyResult = await client.getKey('cipherbox/ipns-republish', `epoch-${epoch}`);
48→    privateKey = keyResult.asUint8Array().slice(0, 32);
49→  } else {
50→    // Simulator: deterministic HKDF derivation from fixed seed
51→    const seed = new TextEncoder().encode('cipherbox-tee-simulator-seed');
52→    const salt = new TextEncoder().encode('cipherbox-dev');
53→    const info = new TextEncoder().encode(`epoch-${epoch}`);
54→    privateKey = hkdf(sha256, seed, salt, info, 32);
55→  }
56→
57→  // Derive uncompressed public key (65 bytes, 0x04 prefix)
58→  const publicKey = secp.getPublicKey(privateKey, false);
59→
60→  // Cache public key for this epoch
61→  publicKeyCache.set(epoch, publicKey);
62→
63→  return { publicKey, privateKey };
64→}
65→
66→/**
67→ * Get the cached public key for an epoch, or derive it.
68→ *
69→ * @param epoch - The key epoch number
70→ * @returns 65-byte uncompressed secp256k1 public key
71→ */
72→export async function getPublicKey(epoch: number): Promise<Uint8Array> {
73→  const cached = publicKeyCache.get(epoch);
74→  if (cached) {
75→    return cached;
76→  }
77→
78→  const { publicKey } = await getKeypair(epoch);
79→  return publicKey;
80→}
